/**
 * @name Server-Side Request Forgery (SSRF)
 * @description Detects potential SSRF vulnerabilities where user input flows to HTTP requests
 * @kind path-problem
 * @problem.severity error
 * @id py/ssrf
 * @tags security
 *       external/cwe/cwe-918
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module SSRFConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource or
    exists(DataFlow::CallCfgNode call |
      call = API::moduleImport("os").getMember("environ").getMember("get").getACall() and
      source = call
    )
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // urllib3 requests
      call = API::moduleImport("urllib3").getMember(["request", "urlopen"]).getACall() and
      sink = call.getArg(0)
      or
      // urllib requests
      call = API::moduleImport("urllib").getMember("request").getMember(["urlopen", "Request"]).getACall() and
      sink = call.getArg(0)
      or
      // http.client requests
      call = API::moduleImport("http").getMember("client").getMember(["HTTPConnection", "HTTPSConnection"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module SSRFFlow = TaintTracking::Global<SSRFConfig>;
import SSRFFlow::PathGraph

from SSRFFlow::PathNode source, SSRFFlow::PathNode sink
where SSRFFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SSRF vulnerability from $@.", source.getNode(), "user-controlled source"

/**
 * @name SQL Injection
 * @description Detects SQL injection vulnerabilities
 * @kind path-problem
 * @problem.severity error
 * @id py/sql-injection
 * @tags security
 *       external/cwe/cwe-089
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.Concepts

module SqlInjectionConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(SqlExecution sql |
      sink = sql.getSql()
    )
  }
}

module SqlInjectionFlow = TaintTracking::Global<SqlInjectionConfig>;
import SqlInjectionFlow::PathGraph

from SqlInjectionFlow::PathNode source, SqlInjectionFlow::PathNode sink
where SqlInjectionFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential SQL injection from $@.", source.getNode(), "user-controlled source"

/**
 * @name XML External Entity (XXE) vulnerability
 * @description Detects unsafe XML parsing that could lead to XXE attacks
 * @kind path-problem
 * @problem.severity error
 * @id py/xxe-vulnerability
 * @tags security
 *       external/cwe/cwe-611
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module XXEConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      // xml.etree.ElementTree.parse or fromstring
      call = API::moduleImport("xml").getMember("etree").getMember("ElementTree").getMember(["parse", "fromstring", "XML"]).getACall() and
      sink = call.getArg(0)
      or
      // xml.dom.minidom.parse or parseString
      call = API::moduleImport("xml").getMember("dom").getMember("minidom").getMember(["parse", "parseString"]).getACall() and
      sink = call.getArg(0)
      or
      // lxml.etree without safe parser
      call = API::moduleImport("lxml").getMember("etree").getMember(["parse", "fromstring", "XML"]).getACall() and
      sink = call.getArg(0)
    )
  }
}

module XXEFlow = TaintTracking::Global<XXEConfig>;
import XXEFlow::PathGraph

from XXEFlow::PathNode source, XXEFlow::PathNode sink
where XXEFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential XXE vulnerability from $@.", source.getNode(), "user-controlled source"
